from continue_readability import checked,fresh,pin,read,run
p=argparse.ArgumentParser(description=__doc__)
for name in ('state','protocols','capture-proof','behavior','output'):p.add_argument('--'+name,type=Path,required=True)
a=p.parse_args();assert not a.output.exists();s=read(a.state);c=read(s['Naming']['BlockCursor']);protocols=read(a.protocols);proof=read(a.capture_proof);behavior=read(a.behavior)
assert protocols['Component']==c['NextPrivateComponent'] and protocols['FixedFindingsPending']==25 and proof['Protocols']==pin(a.protocols) and proof['Compiled']==protocols['CurrentCompiled'] and proof['CompleteLeafBodyVerified'] and proof['InitializationSlicesVerified'] and proof['WholeModuleCaptureUsesVerified']
assert behavior['Cases']==12 and behavior['OriginalRebuiltObservationsEqual'] and pin(proof['Inspector']['Path'])==proof['Inspector']
for path,sha in behavior['Pins'].items():assert pin(path)['Sha256']==sha
original=protocols['OriginalModule'];current=protocols['CurrentCompiled'];assert pin(original['Input'])['Sha256']==original['InputSha256'] and pin(current['Path'])==current
a.output.mkdir();old_types=checked(protocols['OriginalTypes'])['Types'];new_types=checked(protocols['CurrentTypes'])['Types'];old_tokens=[t['Token'] for t in old_types if t['Type'].startswith('asi/')];new_tokens=[t['Token'] for t in new_types if t['Type'].startswith('asi/')];assert len(old_tokens)==4 and len(new_tokens)==5
reader='D:/knx_analysis/capture-environment-reference-native-build03/NameCandidates.dll';old_refs=a.output/'original-frame-references.json';new_refs=a.output/'current-frame-references.json'
run(['dotnet',reader,'--inspect-environment-references',original['Input'],str(old_refs),*old_tokens],a.output/'original-reader.log');run(['dotnet',reader,'--inspect-environment-references',current['Path'],str(new_refs),*new_tokens],a.output/'current-reader.log')
