fresh(a.output/'lifetime-protocols.json',dict(Kind='FixedWholeHttpProgressCaptureLifetimeProtocols',WholeOwnerProtocols=pin(a.protocols),CaptureInitializationProof=pin(a.capture_proof),BoundedBehavior=pin(a.behavior),OriginalFrameReferences=pin(old_refs),CurrentFrameReferences=pin(new_refs),ReferenceReader=pin(reader),CurrentCompleteBodies=protocols['CurrentCompleteBodies'],OriginalCompleteBodies=protocols['OriginalCompleteBodies'],OwnerSource=protocols['OwnerSource'],OriginalFixedFindings=protocols['FixedOriginalFindings'],OriginalTypes=5,OriginalMethods=11,CurrentTypes=6,CurrentMethods=12,FixedFindingsPending=25,FindingsRetired=0,CurrentMoveNextToken=move['Token'],ExceptionHandlers=move['ExceptionHandlers'],NormalInstructions=271,ParentStoreInstruction=proof['ParentStoreInstruction'],ProgressStoreInstruction=proof['ProgressStoreInstruction'],PhysicalProgressArgument=2,
    RequiredProofs=['Trace the captured object from allocation through parent initialization to both await suspension/resumption states;include finally/catch entry and cleanup.','Prove every progress read and delegate-cache construction/use is tied to the same initialized instance;retain compiler extras separately.','Before native rewriting,prevalidate the complete group,compare reconstructed callback/body semantics,and reject changed writes,inputs,branches or handler regions.'],NamesChanged=0,SourceEdited=False,NewOriginalCohortDiscovery=[],AdditionalCompilerScaffolds=protocols['AdditionalCompilerScaffoldsObserved'],InstalledEtsRuntimeVerified=False))
print(dict(OriginalTypes=5,OriginalMethods=11,CurrentFrames=5,AsyncHandlers=3,CallbackBehaviorCases=12,FixedFindingsPending=25,FindingsRetired=0,Output=str(a.output/'lifetime-protocols.json')))
